/**
 * Credential-to-destination scoping acceptance tests: bridge route/header
 * units (T2/T3) and bridge-token shape (T1 token half).
 *
 * Pure unit pins over exported helpers — no servers, no bridge startup. All
 * pass on the pre-fix tree as behavior controls: the Builder must keep them
 * green while fixing the E2E failures in
 * execution-target.credential-scoping.test.ts. Do not edit this file.
 */
import { describe, expect, it } from "vitest";

import {
  authorizeSandboxCallbackBridgeRequestWithRoutes,
  compareBridgeTokensConstantTime,
  createSandboxCallbackBridgeToken,
  DEFAULT_SANDBOX_CALLBACK_BRIDGE_HEADER_ALLOWLIST,
  sanitizeSandboxCallbackBridgeHeaders,
} from "./sandbox-callback-bridge.js";

describe("bridge route and header scoping units", () => {
  it("T2.4: the route allowlist admits the heartbeat surface and rejects absolute, foreign, and lookalike targets", () => {
    const allowed: Array<[string, string]> = [
      ["GET", "/api/agents/me"],
      ["GET", "/api/openapi.json"],
      ["POST", "/api/issues/issue-1/comments"],
      ["POST", "/api/issues/issue-1/checkout"],
      ["POST", "/runtime-tools/github/credentials"],
    ];
    for (const [method, path] of allowed) {
      expect(authorizeSandboxCallbackBridgeRequestWithRoutes({ method, path })).toBeNull();
    }

    const denied: Array<[string, string]> = [
      // Absolute and foreign targets can never be bridge-relative paths.
      ["GET", "https://evil.example.test/api/agents/me"],
      ["POST", "https://api.github.com/repos/o/r/issues/1/comments"],
      ["GET", "http://127.0.0.1:9/api/agents/me"],
      // Non-allowlisted host routes.
      ["GET", "/api/secret-admin-route"],
      ["POST", "/api/agents/me"],
      ["DELETE", "/api/agents/me"],
      // Lookalikes and traversal outside the anchored patterns.
      ["GET", "/api/openapi.json.evil"],
      ["GET", "/api/agents/me/../../etc/passwd"],
      ["POST", "/api/issues/issue-1/comments/extra/depth"],
    ];
    for (const [method, path] of denied) {
      expect(authorizeSandboxCallbackBridgeRequestWithRoutes({ method, path })).toMatch(/^Route not allowed:/);
    }
  });

  it("T3.3: caller authorization/cookie/capability headers are stripped; the five allowlisted headers pass", () => {
    expect([...DEFAULT_SANDBOX_CALLBACK_BRIDGE_HEADER_ALLOWLIST].sort()).toEqual(
      ["accept", "content-type", "if-match", "if-none-match", "x-paperclip-github-capability"].sort(),
    );

    const sanitized = sanitizeSandboxCallbackBridgeHeaders({
      Accept: "application/json",
      "Content-Type": "application/json",
      "If-Match": "etag-1",
      "If-None-Match": 'W/"etag-2"',
      "X-Paperclip-GitHub-Capability": "capability-sentinel",
      Authorization: "Bearer CALLER-CANARY",
      authorization: "Bearer CALLER-CANARY",
      Cookie: "session=CALLER-CANARY",
      "X-Paperclip-Run-Id": "run-canary",
      "X-Paperclip-Evil": "evil-canary",
      "X-Bridge-Debug": "debug-canary",
      "Proxy-Authorization": "Basic CANARY",
    });

    expect(sanitized).toMatchObject({
      Accept: "application/json",
      "Content-Type": "application/json",
      "If-Match": "etag-1",
      "If-None-Match": 'W/"etag-2"',
      "X-Paperclip-GitHub-Capability": "capability-sentinel",
    });
    const keys = Object.keys(sanitized).map((key) => key.toLowerCase());
    expect(keys).not.toContain("authorization");
    expect(keys).not.toContain("cookie");
    expect(keys).not.toContain("x-paperclip-run-id");
    expect(keys).not.toContain("x-paperclip-evil");
    expect(keys).not.toContain("x-bridge-debug");
    expect(keys).not.toContain("proxy-authorization");
    expect(JSON.stringify(sanitized)).not.toContain("CANARY");
    expect(JSON.stringify(sanitized)).not.toContain("canary");
  });

  it("T2.5: bridge-token comparison rejects wrong, empty, and length-mismatched tokens", () => {
    const token = createSandboxCallbackBridgeToken();
    expect(compareBridgeTokensConstantTime(token, token)).toBe(true);
    expect(compareBridgeTokensConstantTime(token, `${token}x`)).toBe(false);
    expect(compareBridgeTokensConstantTime(token, token.slice(0, -1))).toBe(false);
    expect(compareBridgeTokensConstantTime(token, "")).toBe(false);
    expect(compareBridgeTokensConstantTime(token, null)).toBe(false);
    expect(compareBridgeTokensConstantTime(token, undefined)).toBe(false);
    // The expected side is always a minted token (never empty); empty-vs-empty
    // is outside the comparison contract and intentionally unasserted here.
  });

  it("T1.7: minted bridge tokens are random opaque base64url, never JWT-shaped", () => {
    const first = createSandboxCallbackBridgeToken();
    const second = createSandboxCallbackBridgeToken();
    for (const token of [first, second]) {
      expect(token).toMatch(/^[A-Za-z0-9_-]+$/);
      expect(token).not.toContain(".");
      expect(token.length).toBeGreaterThanOrEqual(32);
    }
    expect(first).not.toBe(second);
  });
});
